 "content": "from collections import Counter


def transform(grid):
    """Combine two equal-sized grids separated by a central divider."""
    height, width = len(grid), len(grid[0])
    divider = width // 2
    panel_width = divider
    if width - divider - 1 != panel_width:
        raise ValueError("panels have unequal widths")

    left = [row[:divider] for row in grid]
    right = [row[divider + 1:] for row in grid]
    left_bg = Counter(cell for row in left for cell in row).most_common(1)[0][0]
    right_bg = Counter(cell for row in right for cell in row).most_common(1)[0][0]
    left_colors = {cell for row in left for cell in row}
    right_colors = {cell for row in right for cell in row}

    if left_bg == right_bg:
        return [
            [2 if left[r][c] != left_bg or right[r][c] != right_bg else 3
             for c in range(panel_width)]
            for r in range(height)
        ]

    if right_bg in left_colors:
        return [
            [3 if left[r][c] == right_bg and right[r][c] == right_bg else right_bg
             for c in range(panel_width)]
            for r in range(height)
        ]

    if left_bg in right_colors:
        return [
            [3 if right[r][c] == left_bg and left[r][c] == left_bg else left_bg
             for c in range(panel_width)]
            for r in range(height)
        ]

    raise ValueError("no cross-panel background/motif match")
